@page "/track/{TrackingNumber}"
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment - @TrackingNumber</PageTitle>

<div class="row justify-content-center mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number"
                   @bind="searchNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@string.IsNullOrWhiteSpace(searchNumber)">
                Track
            </button>
        </div>
    </div>
</div>

@if (loading)
{
    <div class="text-center my-4">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (shipment is null)
{
    <div class="alert alert-warning text-center" role="alert">
        <h4 class="alert-heading">Shipment Not Found</h4>
        <p>No shipment was found with tracking number <strong>@TrackingNumber</strong>. Please check the number and try again.</p>
    </div>
}
else
{
    <div class="row justify-content-center">
        <div class="col-md-8">
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
                    <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <div class="row mb-3">
                        <div class="col-sm-6">
                            <strong>Origin:</strong>
                            <p>@shipment.Origin</p>
                        </div>
                        <div class="col-sm-6">
                            <strong>Destination:</strong>
                            <p>@shipment.Destination</p>
                        </div>
                    </div>
                    <div class="row mb-3">
                        <div class="col-sm-6">
                            <strong>Recipient:</strong>
                            <p>@shipment.RecipientName</p>
                        </div>
                        <div class="col-sm-6">
                            <strong>Description:</strong>
                            <p>@shipment.Description</p>
                        </div>
                    </div>
                    <div class="row">
                        <div class="col-sm-4">
                            <strong>Shipped Date:</strong>
                            <p>@shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                        </div>
                        <div class="col-sm-4">
                            <strong>Estimated Delivery:</strong>
                            <p>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                        </div>
                        <div class="col-sm-4">
                            <strong>Actual Delivery:</strong>
                            <p>@(shipment.ActualDelivery?.ToString("MMM dd, yyyy") ?? "—")</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private ShipmentTracker.Client.Models.Shipment? shipment;
    private bool loading = true;
    private string? searchNumber;

    protected override async Task OnParametersSetAsync()
