 @page "/shipments"
 @attribute [Authorize]
 @using Microsoft.AspNetCore.Authorization
 @inject ShipmentTracker.Client.Services.IShipmentService ShipmentService

 <PageTitle>Shipments Dashboard</PageTitle>

 <h3 class="mb-4">Shipments Dashboard</h3>

 <div class="mb-3">
     <label class="form-label fw-bold">Filter by Status:</label>
     <select class="form-select w-auto d-inline-block" @bind="selectedFilter">
         <option value="">All</option>
         @foreach (var status in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
         {
             <option value="@status">@status</option>
         }
     </select>
 </div>

 @if (loading)
 {
     <div class="text-center my-4">
         <div class="spinner-border text-primary" role="status">
             <span class="visually-hidden">Loading...</span>
         </div>
         <p class="mt-2 text-muted">Loading shipments...</p>
     </div>
 }
 else
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead class="table-dark">
                 <tr>
                     <th>Tracking #</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Status</th>
                     <th>Shipped Date</th>
                     <th>Est. Delivery</th>
                     <th>Update Status</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var shipment in FilteredShipments)
                 {
                     <tr>
                         <td><a href="/track/@shipment.TrackingNumber">@shipment.TrackingNumber</a></td>
                         <td>@shipment.Origin</td>
                         <td>@shipment.Destination</td>
                         <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                         <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                         <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                         <td>
                             <select class="form-select form-select-sm" value="@shipment.Status"
                                     @onchange="e => UpdateStatus(shipment, e)">
                                 @foreach (var status in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
                                 {
                                     <option value="@status" selected="@(shipment.Status == status)">@status</option>
                                 }
                             </select>
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>

     @if (!FilteredShipments.Any())
     {
         <div class="alert alert-info">No shipments match the selected filter.</div>
     }
 }

 @code {
     private List<ShipmentTracker.Client.Models.Shipment> shipments = [];
     private bool loading = true;
     private string selectedFilter = "";

     private IEnumerable<ShipmentTracker.Client.Models.Shipment> FilteredShipments =>
         string.IsNullOrEmpty(selectedFilter)
             ? shipments
             : shipments.Where(s => s.Status.ToString() == selectedFilter);

     protected override async Task OnInitializedAsync()
     {
         shipments = await ShipmentService.GetAllShipmentsAsync();
         loading = false;
     }

     private async Task UpdateStatus(ShipmentTracker.Client.Models.Shipment shipment, ChangeEventArgs e)
     {
         if (Enum.TryParse<ShipmentTracker.Client.Models.ShipmentStatus>(e.Value?.ToString(), out var newStatus))
         {
             await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
             shipment.Status = newStatus;
             if (newStatus == ShipmentTracker.Client.Models.ShipmentStatus.Delivered)
                 shipment.ActualDelivery = DateTime.UtcNow;
         }
     }

     private static string GetStatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
     {
         ShipmentTracker.Client.Models.ShipmentStatus.Pending => "bg-secondary",
         ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => "bg-info text-dark",
         ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-warning text-dark",
         ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-primary",
         ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
         ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-danger",
         ShipmentTracker.Client.Models.ShipmentStatus.Returned => "bg-dark",
         _ => "bg-secondary"
     };
 }

