     {
         if (e.Key == "Enter")
             Search();
     }

     private static string GetStatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
     {
         ShipmentTracker.Client.Models.ShipmentStatus.Pending => "bg-secondary",
         ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => "bg-info text-dark",
         ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-warning text-dark",
         ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-primary",
         ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
         ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-danger",
         ShipmentTracker.Client.Models.ShipmentStatus.Returned => "bg-dark",
         _ => "bg-secondary"
     };
 }

